# نکته مهم: Replication Lag
# ================================
# Replica چند میلی‌ثانیه عقب‌تر از Primary است.
# مشکل: کاربر ثبت‌نام می‌کند، بعد login می‌کند،
# اما Replica هنوز user را ندارد.


class SmartRouter(PrimaryReplicaRouter):
    """
    اگر کاربر قبلاً نوشته باشد،
    برای مدتی خواندن‌ها را به Primary می‌فرستد.
    """

    def db_for_read(self, model, **hints):
        # اگر در همان درخواست، نوشتنی انجام شده
        if hasattr(self, "_just_wrote") and self._just_wrote:
            return "default"
        return super().db_for_read(model, **hints)

    def db_for_write(self, model, **hints):
        self._just_wrote = True
        return "default"

from django.db import transaction


@transaction.atomic(using="default")
def register_user(username, email, password):
    """ثبت‌نام — روی Primary."""
    user = User.objects.create_user(username=username, email=email, password=password)
    return user


def get_user_after_register(user_id):
    """
    بلافاصله بعد از ثبت‌نام،
    از Primary بخوان تا مشکل lag نداشته باشیم.
    """
    return User.objects.using("default").get(pk=user_id)

